import React, { Component } from 'react';
import './Portfolio.css';

class Portfolio extends Component {
  constructor(props) {
    super(props);
    this.state = {
      projects: [
        {
          project_image: `${process.env.PUBLIC_URL || ''}/project1.jpg`,
          title: "E-commerce Website",
          description: "A full-stack e-commerce platform built with React and Node.js",
          technologies: ["React", "Node.js", "MongoDB", "CSS3"],
        },
        {
          project_image: `${process.env.PUBLIC_URL || ''}/project2.jpg`,
          title: "Task Management App",
          description: "A collaborative task management application with real-time updates",
          technologies: ["React", "Socket.io", "Express", "PostgreSQL"],
        },
      ]
    };
  }

  render() {
    return (
      <div className="portfolio-section">
        <h2 className="portfolio-title">Portfolio</h2>
        <div className="portfolio-grid">
          {this.state.projects.map((project, index) => (
            <div key={index} className="portfolio-card">
              <div className="portfolio-card-image">
                {project.project_image ? (
                  <>
                    <img
                      src={project.project_image}
                      alt={project.title}
                      onError={(e) => {
                        e.target.style.display = 'none';
                        const placeholder = e.target.nextElementSibling;
                        if (placeholder) placeholder.style.display = 'flex';
                      }}
                    />
                    <div className="portfolio-image-placeholder" style={{ display: 'none' }}>Project Image</div>
                  </>
                ) : (
                  <div className="portfolio-image-placeholder">Project Image</div>
                )}
              </div>
              <div className="portfolio-card-body">
                <h3 className="portfolio-card-title">{project.title}</h3>
                <p className="portfolio-card-description">{project.description}</p>
                <div className="portfolio-technologies">
                  {project.technologies.map((tech, techIndex) => (
                    <span key={techIndex} className="portfolio-tech-tag">{tech}</span>
                  ))}
                </div>
                <div className="portfolio-card-buttons">
                  <button type="button" className="portfolio-btn portfolio-btn-primary">Live Demo</button>
                  <button type="button" className="portfolio-btn portfolio-btn-secondary">Source Code</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }
}

export default Portfolio;
